    /** 
     * Devuelve el SVG solicitado.
     *
     * @param string      $name  Clave del icono.
     * @param string|null $class Clases CSS extra para <svg>.
     * @return string
     */
    public static function icon(string $name, ?string $class = null): string
    {

        if (empty(self::$icons[$name])) {
            return '';           // icono no existente
        }

        $svg = trim(self::$icons[$name]);

        // Inyecta clases, si se proporcionan
        if ($class) {
            $svg = preg_replace(
                '/^<svg\b([^>]*)>/',
                '<svg$1 class="' . esc_attr($class) . '">',
                $svg,
                1
            );
        }

        return $svg;             // Se asume sanitizado de antemano
    }
}
